<!-- wp:heading -->
<h2 class="wp-block-heading">The principles behind the <em>process.</em></h2>
<!-- /wp:heading -->
<!-- wp:paragraph -->
<p>Trading on your own means nobody else sets the rules. These three come first.</p>
<!-- /wp:paragraph -->
</div>
<!-- /wp:group -->
<!-- wp:group {"className":"prin-grid","layout":{"type":"default"}} -->
<div class="wp-block-group prin-grid">
